module default {
    type Warehouse {
        required code: str {
            constraint exclusive;
        }
        required region: str;

        required single shelf_units := (
            with s := (select .<warehouse[is ShelfCount])
            select coalesce(sum(s.quantity), 0)
        );

        required single ledger_units := (
            with l := (select .<warehouse[is LedgerLine])
            select coalesce(sum(l.quantity), 0)
        );

        multi counted_skus := (
            select distinct (select .<warehouse[is ShelfCount]).sku
        );

        multi ledger_skus := (
            select distinct (select .<warehouse[is LedgerLine]).sku
        );

        multi unreconciled_skus := (
            .counted_skus symmetric difference .ledger_skus
        );

        required single is_balanced := (
            not exists .unreconciled_skus
            and .shelf_units = .ledger_units
        );
    }

    type Sku {
        required code: str {
            constraint exclusive;
        }
        required label: str;

        single sole_warehouse := (
            with shelf_wh := (select .<sku[is ShelfCount].warehouse),
                distinct_wh := (select distinct shelf_wh),
            select distinct_wh
            if count(distinct_wh) = 1
            else (select Warehouse filter false)
        );
    }

    type ShelfCount {
        required warehouse: Warehouse;
        required sku: Sku;
        required quantity: int64;
        required tag: str;
    }

    type LedgerLine {
        required warehouse: Warehouse;
        required sku: Sku;
        required quantity: int64;
        required tag: str;
    }
}

